import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十卦 履 天泽履 乾上兑下","description":"周易 - 第十卦 履 天泽履 乾上兑下","frontmatter":{"title":"第十卦 履 天泽履 乾上兑下","description":"周易 - 第十卦 履 天泽履 乾上兑下"},"headers":[],"relativePath":"zh/classics/zhouyi/011.md","filePath":"zh/classics/zhouyi/011.md"}'),l={name:"zh/classics/zhouyi/011.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="履" tabindex="-1">履 <a class="header-anchor" href="#履" aria-label="Permalink to “履”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>履虎尾，不咥人，亨。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。刚中正，履帝位而不疚，光明也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>上天下泽，履；君子以辨上下，安民志。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>素履，往无咎。象曰：素履之 往，独行愿也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>履道坦坦，幽人贞吉。象曰：幽人贞吉，中不自乱也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>眇能视，跛能履，履虎尾，咥人，凶。武人为于大君。象曰：眇能视；不足以有明也。跛能履；不足以与行也。咥人之凶；位不当也。武人为于大君；志刚也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>履虎尾，愬愬终吉。象曰：愬愬终吉，志行也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>夬履，贞厉。象曰：夬履贞厉，位正当也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>视履考祥，其旋元吉。象曰：元吉在上，大有庆也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
